import {createCompanionSovereigntyExecutor} from '../portability/companion-sovereignty-executor.js';
import {createCompanionLocalAiAdapter} from '../portability/companion-local-ai-adapter.js';


// MEL-UI-AUDIT-05: a deterministic *offline* acceptance classifier. A
// simulated browser/worker receipt is never independent physical hardware
// evidence. The classifier is read-only: it does not execute device commands.
export function classifyCompanionHardwareControl(control, observation = {}) {
 const id=String(control||'').trim();
 const status=String(observation?.status||'').toUpperCase();
 const source=String(observation?.source||'').toLowerCase();
 const receipt=observation?.physical_receipt;
 const blocked=reason=>({control:id,status:'BLOCKED',reason,physical_verified:false});
 if(!id)return blocked('CONTROL_UNSPECIFIED');
 const refusal=companionBlockReason(observation);
 if(refusal)return blocked(refusal);
 // Only an independently observed device receipt can satisfy an on-device
 // hardware acceptance. Test doubles, untrusted source fields and a bare
 // success boolean are not proof of a physical action.
 if(source!=='paired-windows-companion' || observation?.simulated===true
    || observation?.ok!==true || status!=='SUCCESS'
    || receipt?.kind!=='ON_DEVICE_OBSERVED'
    || String(receipt?.control||'')!==id
    || !String(receipt?.device_id||'').trim()
    || !Number.isSafeInteger(receipt?.observed_at) || receipt.observed_at<=0)
   return blocked('PHYSICAL_PROOF_MISSING');
 // This offline recipe has no authenticated server lookup. A well-shaped
 // client claim is still unverified; real device acceptance is separate.
 return blocked('PHYSICAL_PROOF_UNVERIFIED');
}

function companionBlockReason(observation={}){
 const status=String(observation?.status||'').trim().toUpperCase();
 const code=String(observation?.code||'').trim().toUpperCase();
 if(observation?.halted===true || ['HALTED','STOPPED'].includes(status)
   || ['OWNER_HALT_ACTIVE','COMPUTER_HALTED','LOCAL_COMPUTE_DISABLED'].includes(code))return 'OWNER_STOPPED';
 if(String(observation?.permission||'').toUpperCase()==='DENIED'
   || ['DENIED','PERMISSION_DENIED'].includes(status)
   || ['PERMISSION_DENIED','COMPUTER_PERMISSION_DENIED','FORBIDDEN',
       'REMOTE_ACCESS_DISABLED_LOCALLY','COMPUTER_PERMISSION_REVOKED','COMPANION_PERMISSION_CHANGED'].includes(code))return 'PERMISSION_DENIED';
 if(observation?.online===false || status==='OFFLINE'
   || ['COMPUTER_OFFLINE','COMPUTER_DEVICE_OFFLINE','COMPUTER_ENGINE_OFFLINE',
       'COMPUTER_ENGINE_UNVERIFIED','COMPANION_SOVEREIGNTY_TIMEOUT','NETWORK_OFFLINE'].includes(code))return 'COMPUTER_OFFLINE';
 return ['FAILED','CANCELLED'].includes(status)?'COMPANION_CONTROL_BLOCKED':null;
}

// Optional only. "Prefer PC" must be explicit on the request AND the
// owner's separate Windows consent must be admitted by the executor.
// Without this flag MEL keeps its original primary cloud route.
export function shouldPreferOptionalCompanionCompute({
 prefer=false,disabled=false,voiceReply=false,personalProfileIntent=false,
 releaseSmoke=false,privateData=false,hasToolResults=false,parallel=false,
 hasActiveAdapter=false
}={}){
 return prefer===true && disabled!==true && !voiceReply && !personalProfileIntent
   && !releaseSmoke && !privateData && !hasToolResults && !parallel
   && !hasActiveAdapter;
}

export async function tryOptionalNativeCompanionFallback({
 env,messages,inferenceSettings=null,execute=null,asPrimary=false,timeoutMs=12000
}={}){
 if(!env?.DB && typeof execute!=='function')return null;
 if(!Array.isArray(messages)||messages.length<1)return null;
 // Keep the conversation transfer to the owner's computer explicitly bounded.
 const permitted=new Set(['system','assistant','user']);
 const bounded=messages.slice(-8).map(m=>({
   role:String(m?.role||'user'),content:String(m?.content||'')
 }));
 if(bounded.some(m=>!permitted.has(m.role)||m.content.length>12000))return null;
 if(bounded.reduce((sum,m)=>sum+m.content.length,0)>24000)return null;
 try{
   const boundedTimeout=Math.max(1000,Math.min(12000,Number(timeoutMs)||12000));
   const executor=execute||createCompanionSovereigntyExecutor(env,{
     timeoutMs:boundedTimeout,pollIntervalMs:250
   });
   const adapter=createCompanionLocalAiAdapter({execute:async input=>{
     const result=await executor(input);
     // A legacy command envelope may say SUCCEEDED while its payload carries
     // a device refusal. Never turn the accompanying stale text into success.
     if(companionBlockReason(result))
       return {ok:false,code:'COMPANION_CONTROL_BLOCKED'};
     return result;
   }});
   const answer=await adapter.invoke({input:bounded,context:{
     inference_settings:{
       temperature:inferenceSettings?.temperature??0.2,
       max_tokens:Math.min(512,Math.max(1,Number(inferenceSettings?.max_tokens)||360))
     }
   }});
   const text=String(answer?.text||'').trim();
   if(!text)return null;
   return {
     text,model:answer?.provenance?.model||'auto-local',
     provider:'local-companion-ai',task:'GENERAL',attempts:1,
     fallback_used:!asPrimary,optional_companion_used:true,
     companion_primary:asPrimary===true,
     tool_succeeded:true,finish_reason:null,truncated:false,
     provenance:{...answer.provenance,hardware_test_performed:false,evidence_scope:'INFERENCE_RESPONSE'},
     usage:null
   };
 }catch{return null;}
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { runInNewContext } from 'node:vm';
import { onRequestGet } from '../src/pages/full-interface-v2.js';

test('full interface exposes the Computer tab and installer',async()=>{
  const response=await onRequestGet();
  const html=await response.text();
  assert.match(html,/data-view="computer"/);
  assert.match(html,/data-panel="computer"/);
  assert.match(html,/\/api\/computer\/v1\/installer/);
  assert.match(html,/ARRÊTER LE CONTRÔLE/);
  assert.match(html,/computerScreen/);
});

test('offline hardware recipe blocks missing evidence and never performs a device command',async()=>{
 const {offlineHardwareControlReceipt}=await import('../scripts/ui-production-audit.mjs');
 const report=offlineHardwareControlReceipt([
   {control:'screen',online:false,code:'COMPUTER_OFFLINE'},
   {control:'keyboard',permission:'DENIED'},
   {control:'mouse',halted:true},
   {control:'stop',source:'mock',status:'SUCCESS',ok:true,
     physical_receipt:{kind:'ON_DEVICE_OBSERVED',control:'stop',device_id:'test',observed_at:5}}
 ]);
 assert.equal(report.schema,'mel.ui-hardware-offline-receipt/v1');
 assert.deepEqual(report.controls.map(x=>x.reason),
   ['COMPUTER_OFFLINE','PERMISSION_DENIED','OWNER_STOPPED','PHYSICAL_PROOF_MISSING']);
 assert.equal(report.pass,0);
 assert.equal(report.blocked,4);
 assert.equal(report.mutations_performed,0);
 assert.equal(report.simulated_physical_passes,0);
});

test('software-only recipe executes the real UI guards without dispatching hardware commands',async()=>{
 const html=await(await onRequestGet()).text();
 const selected=html.slice(html.indexOf('function selectedComputer()'),html.indexOf('function fmtSeen('));
 const readiness=html.slice(html.indexOf('function companionDesktopReadiness('),html.indexOf('function renderComputer('));
 const command=html.slice(html.indexOf('async function computerCommand('),html.indexOf("qs('#computerRefresh').onclick="));
 assert.ok(selected&&readiness&&command,'exercise the functions shipped in the real page');
 const now=Date.now();
 const healthy={id:'software-fixture',online:true,halted:false,last_seen_at:now,
  metadata:{remote_access_enabled:true,engine_heartbeat_at:now,engine_direct_heartbeat_at:now}};
 const cases=[
  ['COMPUTER_DEVICE_OFFLINE',{...healthy,online:false}],
  ['REMOTE_ACCESS_DISABLED_LOCALLY',{...healthy,metadata:{...healthy.metadata,remote_access_enabled:false}}],
  ['OWNER_HALT_ACTIVE',{...healthy,halted:true}],
 ];
 let requests=0;
 for(const [code,device] of cases){
  const context={computerCache:{devices:[device]},Date,Number,Error,
   qs:()=>({value:''}),jfetch:async()=>{requests++;throw Error('MUST_NOT_DISPATCH');}};
  const api=runInNewContext(selected+'\n'+readiness+'\n'+command+'\n({computerCommand,companionDesktopReadiness})',context,{timeout:1000});
  assert.equal(api.companionDesktopReadiness(device,now).code,code);
  for(const steps of [[{action:'screen.capture'}],[{action:'app.open',app:'notepad'}],
   [{action:'keyboard.type',text:'software guard recipe'}]])
   await assert.rejects(()=>api.computerCommand(steps,steps[0].action!=='screen.capture'),error=>error.message===code);
  assert.equal(requests,0,'offline, denied and halted UI paths cannot reach the command API');
  assert.equal(api.companionDesktopReadiness(healthy,now).ok,true,'the healthy control path remains available');
 }
 // This is a software guard recipe over the real UI source, not a PC capture.
 assert.equal(requests,0);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {tryOptionalNativeCompanionFallback as fallback} from '../src/api/native-companion-fallback.js';

test('native-chat invokes owner Companion only after ordinary cloud fallbacks',async()=>{
 const s=await readFile(new URL('../src/api/native-chat.js',import.meta.url),'utf8');
 const cloud=s.indexOf('for (const attempt of attempts)',s.indexOf('const fallbackModels ='));
 const local=s.indexOf('recovered = await tryOptionalNativeCompanionFallback({',cloud);
 assert.ok(cloud>0&&local>cloud);
 assert.match(s,/!privateConnectedDataRequest\(activeTaskText\)/);
 assert.match(s,/body.use_companion_compute !== false/);
 assert.match(s,/toolResults.length === 0/);
});
test('real executor result becomes a usable native-chat response',async()=>{
 const calls=[];
 const answer=await fallback({
   env:{},messages:[{role:'user',content:'Bonjour'}],
   inferenceSettings:{max_tokens:90},
   execute:async input=>{
     calls.push(input);
     return {ok:true,text:'Salut, je suis MEL sur ton PC',model:'qwen2.5:1.5b',
       backend:'ollama-localhost',inference_metrics:{output_tokens:12,eval_duration_ns:1e9,
       tokens_per_second:12,gpu_vram_bytes:0,gpu_evidence:'UNVERIFIED'}};
   }
 });
 assert.equal(calls.length,1);
 assert.equal(calls[0].action,'invoke');
 assert.equal(calls[0].payload.max_tokens,90);
 assert.equal(answer.text,'Salut, je suis MEL sur ton PC');
 assert.equal(answer.optional_companion_used,true);
 assert.equal(answer.provenance.performance.tokens_per_second,12);
});
test('offline, failure, or oversize payload produce quiet primary MEL fallback',async()=>{
 const messages=[{role:'user',content:'Bonjour'}];
 assert.equal(await fallback({env:{},messages}),null);
 assert.equal(await fallback({env:{},messages,execute:async()=>({ok:false,code:'LOCAL_COMPUTE_DISABLED'})}),null);
 assert.equal(await fallback({env:{},messages,execute:async()=>{throw Error('offline')}}),null);
 assert.equal(await fallback({env:{},messages:[{role:'user',content:'x'.repeat(25000)}],execute:async()=>{throw Error('MUST_NOT_CALL')}}),null);
});

test('owner may explicitly prefer a quick optional local-first answer without changing defaults',async()=>{
 const {shouldPreferOptionalCompanionCompute:prefer}=await import('../src/api/native-companion-fallback.js');
 assert.equal(prefer({}),false);
 assert.equal(prefer({prefer:true}),true);
 for(const constraint of [
  {disabled:true},{voiceReply:true},{personalProfileIntent:true},{releaseSmoke:true},
  {privateData:true},{hasToolResults:true},{parallel:true},{hasActiveAdapter:true}
 ]) assert.equal(prefer({prefer:true,...constraint}),false,JSON.stringify(constraint));
});
test('explicit local-first response is not misrepresented as a fallback',async()=>{
 const {shouldPreferOptionalCompanionCompute:prefer}=await import('../src/api/native-companion-fallback.js');
 const native=await readFile(new URL('../src/api/native-chat.js',import.meta.url),'utf8');
 assert.equal(prefer({prefer:true}),true);
 const local=native.indexOf('ai = preferLocal ? await tryOptionalNativeCompanionFallback({');
 const primary=native.indexOf('if(!ai) ai = await runNativeInference({',local);
 assert.ok(local>0&&primary>local);
 assert.match(native.slice(local,primary),/asPrimary:true,timeoutMs:4000/);
 const result=await fallback({
   env:{},messages:[{role:'user',content:'bonjour'}],
   timeoutMs:4000,asPrimary:true,
   execute:async()=>({ok:true,text:'Réponse depuis le PC',backend:'ollama-localhost',model:'local-qwen'})
 });
 assert.equal(result.text,'Réponse depuis le PC');
 assert.equal(result.companion_primary,true);
 assert.equal(result.fallback_used,false);
});
test('local-first failures yield null and leave normal remote inference available',async()=>{
 const result=await fallback({env:{},messages:[{role:'user',content:'hi'}],
   asPrimary:true,timeoutMs:4000,execute:async()=>({ok:false,code:'COMPUTER_OFFLINE'})});
 assert.equal(result,null);
});

test('hardware controls fail closed for offline, permission denied and owner stop',async()=>{
 const {classifyCompanionHardwareControl:classify}=await import('../src/api/native-companion-fallback.js');
 for(const control of ['screen','keyboard','mouse','stop']){
   assert.deepEqual(
     {status:classify(control,{online:false,status:'OFFLINE',code:'COMPUTER_OFFLINE'}).status,
      reason:classify(control,{online:false,status:'OFFLINE'}).reason},
     {status:'BLOCKED',reason:'COMPUTER_OFFLINE'});
   assert.equal(classify(control,{permission:'DENIED'}).reason,'PERMISSION_DENIED');
   assert.equal(classify(control,{halted:true}).reason,'OWNER_STOPPED');
 }
});
test('no software simulation can certify a physical hardware control',async()=>{
 const {classifyCompanionHardwareControl:classify}=await import('../src/api/native-companion-fallback.js');
 const physical_receipt={kind:'ON_DEVICE_OBSERVED',control:'screen',device_id:'pc-1',observed_at:123};
 for(const source of ['mock','browser','simulator','worker']){
   const row=classify('screen',{source,status:'SUCCESS',ok:true,physical_receipt});
   assert.equal(row.status,'BLOCKED');
   assert.equal(row.physical_verified,false);
 }
 assert.equal(classify('screen',{source:'paired-windows-companion',simulated:true,status:'SUCCESS',ok:true,physical_receipt}).status,'BLOCKED');
 assert.equal(classify('screen',{source:'paired-windows-companion',status:'SUCCESS',ok:true}).status,'BLOCKED');
 const accepted=classify('screen',{source:'paired-windows-companion',status:'SUCCESS',ok:true,physical_receipt});
 assert.equal(accepted.status,'BLOCKED');
 assert.equal(accepted.physical_verified,false);
 assert.equal(accepted.reason,'PHYSICAL_PROOF_UNVERIFIED');

 assert.equal(classify('keyboard',{source:'paired-windows-companion',status:'SUCCESS',ok:true,physical_receipt}).status,'BLOCKED');
});

for (const code of ['COMPUTER_OFFLINE', 'PERMISSION_DENIED', 'OWNER_HALT_ACTIVE']) {
 test('software recipe refuses a contradictory successful envelope carrying '+code, async()=>{
  let calls=0;
  const result=await fallback({env:{},messages:[{role:'user',content:'bonjour'}],
   execute:async()=>{calls++;return {ok:true,code,text:'stale local text',backend:'software-test-double'};}});
  assert.equal(result,null,'a blocked device receipt must leave the cloud route available');
  assert.equal(calls,1,'a refusal must not retry the local action');
 });
}

test('a software double can never attest a physical hardware test',async()=>{
 const result=await fallback({env:{},messages:[{role:'user',content:'bonjour'}],
  execute:async()=>({ok:true,text:'synthetic response',backend:'software-test-double',hardware_test_performed:true})});
 assert.equal(result.text,'synthetic response');
 assert.equal(result.provenance.hardware_test_performed,false);
 assert.equal(result.provenance.evidence_scope,'INFERENCE_RESPONSE');
});

test('negative device status and halt telemetry override stale successful text',async()=>{
 for(const refusal of [{status:'DENIED'},{status:'OFFLINE'},{status:'HALTED'},
  {halted:true},{online:false},{code:' owner_halt_active '}]){
  assert.equal(await fallback({env:{},messages:[{role:'user',content:'bonjour'}],
   execute:async()=>({ok:true,text:'stale text',...refusal})}),null,JSON.stringify(refusal));
 }
});
